&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td width=&quot;226&quot;&gt;
&lt;p&gt;Accountability&lt;/p&gt;
&lt;/td&gt;
&lt;td width=&quot;531&quot;&gt;
